select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_TARE_HANDOVER','RRL_STOCK_TARE_CMD','RRL_TARE_BOOK_GUARD','RRL_TARE_OFFER_BOOK_GUARD') order by OBJECT_NAME,OBJECT_TYPE;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-10-102-booked-tare-driver-handover';
select count(*) NEGATIVE_AVAILABLE from RRL_TARE_AVAILABILITY where AVAILABLE_QTY<0;
